import React, { useState } from 'react';
import { 
  Box, 
  Button, 
  Card,
  CardContent,
  Container, 
  Divider,
  Grid, 
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Paper,
  Stack, 
  Typography, 
  useTheme,
  useMediaQuery,
  Fade,
  Grow,
  Chip
} from '@mui/material';
import PhoneIcon from '@mui/icons-material/Phone';
import ScheduleIcon from '@mui/icons-material/Schedule';
import { Link } from 'react-router-dom';
import EmailSignInModal from '../../components/EmailSignInModal/EmailSignInModal';
import { 
  CheckCircle as CheckCircleIcon, 
  ArrowForward as ArrowForwardIcon,
  People as PeopleIcon,
  VerifiedUser as VerifiedUserIcon,
  Receipt as ReceiptIcon,
  Assignment as AssignmentIcon,
  Business as BusinessIcon,
  Translate as TranslateIcon,
  Security as SecurityIcon,
  Speed as SpeedIcon,
  ThumbUp as ThumbUpIcon
} from '@mui/icons-material';

// Service data with detailed descriptions and icons
const services = [
  {
    title: 'Individual & Business Tax Preparation',
    description: 'Expert tax preparation services for both individuals and businesses. We maximize your refunds and ensure compliance with all tax regulations.',
    icon: <ReceiptIcon fontSize="large" color="primary" />,
    features: ['Personal Tax Returns', 'Business Tax Returns', 'Tax Planning', 'IRS Representation']
  },
  {
    title: 'ITIN Application Assistance',
    description: 'Professional help with Individual Taxpayer Identification Number applications and renewals for non-residents and foreign nationals.',
    icon: <AssignmentIcon fontSize="large" color="primary" />,
    features: ['New ITIN Applications', 'ITIN Renewals', 'Document Certification', 'Fast Processing']
  },
  {
    title: 'Immigration Forms & Documentation',
    description: 'Comprehensive assistance with all USCIS forms and documentation for various immigration processes.',
    icon: <AssignmentIcon fontSize="large" color="primary" />,
    features: ['Green Card Applications', 'Citizenship (N-400)', 'Work Permits', 'Family Petitions']
  },
  {
    title: 'Translation & Notary Services',
    description: 'Certified document translation and notary services with flexible scheduling and bilingual support.',
    icon: <TranslateIcon fontSize="large" color="primary" />,
    features: ['Document Translation', 'Certified Notary', 'Bilingual Support', 'Mobile Service Available']
  }
];

// Why Choose Us features with unique icons
const features = [
  { 
    text: 'HR Block Certified', 
    description: 'Certified tax preparer with professional training from HR Block.',
    icon: <VerifiedUserIcon color="primary" /> 
  },
  { 
    text: 'Affordable & Transparent', 
    description: 'No hidden fees with clear, upfront pricing for all our services.',
    icon: <ThumbUpIcon color="primary" /> 
  },
  { 
    text: 'Bilingual Team', 
    description: 'Fluent in English and French to serve our diverse community.',
    icon: <TranslateIcon color="primary" /> 
  },
  { 
    text: 'Personalized Service', 
    description: 'Customized solutions tailored to your specific needs and goals.',
    icon: <PeopleIcon color="primary" /> 
  },
  { 
    text: 'Fast & Reliable', 
    description: 'Efficient service with a track record of on-time submissions and approvals.',
    icon: <SpeedIcon color="primary" /> 
  },
  { 
    text: 'Secure & Confidential', 
    description: 'Your privacy is our priority with secure document handling.',
    icon: <SecurityIcon color="primary" /> 
  }
];

// Testimonials data
// const testimonials = [
//   {
//     name: 'Maria G.',
//     role: 'Small Business Owner',
//     content: 'Eagle Vision helped me with my business taxes and saved me thousands. Their team is knowledgeable and professional.',
//     rating: 5
//   },
//   {
//     name: 'James R.',
//     role: 'Individual Taxpayer',
//     content: 'The best tax service I\'ve ever used. They made the process so easy and got me a much bigger refund than I expected!',
//     rating: 5
//   },
//   {
//     name: 'Sofia M.',
//     role: 'Immigration Client',
//     content: 'They guided me through the entire green card process. Couldn\'t have done it without their expertise and support.',
//     rating: 5
//   }
// ];

const Home = () => {
  const [isSignInModalOpen, setIsSignInModalOpen] = useState(false);

  const handleOpenSignInModal = () => {
    setIsSignInModalOpen(true);
  };

  const handleCloseSignInModal = () => {
    setIsSignInModalOpen(false);
  };

  const handleEmailSubmit = async (email) => {
    try {
      // Here you would typically make an API call to your backend
      // to send the verification email
      console.log('Sending verification email to:', email);

      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));

      // On success, the modal will show the verification sent message
      // The actual verification link handling would be done on your backend
      // and would redirect to the appointment booking page with a valid token

    } catch (error) {
      console.error('Error sending verification email:', error);
      throw error; // Let the modal handle the error
    }
  };

  const theme = useTheme();
  // Media query for responsive design
  useMediaQuery(theme.breakpoints.down('md'));

  // Testimonials section has been removed

  return (
    <Box sx={{ 
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      marginTop: { xs: '-40px', sm: '-30px' } // Pull content up
    }}>
      {/* Hero Section with Overlay */}
      <Box sx={{
        background: `linear-gradient(rgba(26, 54, 93, 0.85), rgba(13, 29, 49, 0.85)), url('/images/office-banner.jpg')`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        backgroundRepeat: 'no-repeat',
        pt: { xs: 4, md: 6 },
        pb: { xs: 6, md: 8 },
        display: 'flex',
        alignItems: 'flex-start',
        color: 'white',
        position: 'relative',
        zIndex: 1,
        boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
        minHeight: '60vh',
        justifyContent: 'center',
        flexDirection: 'column'
      }}>
        <Container maxWidth="lg" sx={{ position: 'relative', zIndex: 2, py: { xs: 0, md: 2 } }}>
          <Grid container spacing={4} alignItems="center">
            <Grid item xs={12} lg={7}>
              <Chip 
                label="Trusted Since 2025" 
                color="secondary" 
                size="small" 
                sx={{ 
                  mb: 2, 
                  color: 'white',
                  fontWeight: 600,
                  px: 1,
                  '& .MuiChip-label': { px: 1.5 }
                }} 
              />

              <Typography 
                variant="h1" 
                component="h1"
                sx={{
                  fontWeight: 700,
                  mb: 2,
                  fontSize: { xs: '1.8rem', sm: '2.2rem', md: '2.5rem' },
                  lineHeight: 1.2,
                  color: 'white',
                }}
              >
                Expert Tax & Immigration Services in Your Area
              </Typography>

              <Typography 
                variant="body1" 
                component="p" 
                sx={{ 
                  mb: 3,
                  color: 'rgba(255, 255, 255, 0.9)',
                  fontSize: { xs: '0.95rem', md: '1.05rem' },
                  lineHeight: 1.6,
                  maxWidth: '100%'
                }}
              >
                Professional, affordable, and reliable assistance with tax preparation, 
                immigration forms, and business services. Your success is our priority.
              </Typography>

              <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ mb: 4, maxWidth: '90%' }}>
                <Button
                  variant="contained"
                  color="secondary"
                  component="a"
                  href="tel:4074528792"
                  size="large"
                  startIcon={<PhoneIcon />}
                  sx={{
                    py: 1.8,
                    px: 4,
                    borderRadius: '8px',
                    textTransform: 'none',
                    fontWeight: 600,
                    fontSize: '1.1rem',
                    whiteSpace: 'nowrap',
                    '&:hover': {
                      transform: 'translateY(-2px)',
                      boxShadow: 3,
                      backgroundColor: theme.palette.secondary.dark
                    },
                    transition: 'all 0.3s ease',
                  }}
                >
                  Call Now (407) 452-8792
                </Button>

                <Button
                  variant="outlined"
                  color="inherit"
                  component={Link}
                  to="/contact"
                  size="large"
                  endIcon={<ArrowForwardIcon />}
                  sx={{
                    py: 1.8,
                    px: 4,
                    borderRadius: '8px',
                    textTransform: 'none',
                    fontWeight: 600,
                    fontSize: '1.1rem',
                    borderWidth: '2px',
                    color: 'white',
                    borderColor: 'rgba(255, 255, 255, 0.3)',
                    '&:hover': {
                      backgroundColor: 'rgba(255, 255, 255, 0.1)',
                      borderColor: 'white',
                      transform: 'translateY(-2px)'
                    },
                    transition: 'all 0.3s ease',
                    whiteSpace: 'nowrap'
                  }}
                >
                  Free Consultation
                </Button>

              </Stack>

              <Box sx={{ mt: 2, textAlign: 'center' }}>
                <Typography variant="body2" sx={{ color: 'rgba(255, 255, 255, 0.8)', mb: 2, fontSize: '1rem' }}>
                  Or book your appointment online now
                </Typography>

                <Button
                  variant="contained"
                  color="secondary"
                  onClick={handleOpenSignInModal}
                  size="large"
                  startIcon={<ScheduleIcon />}
                  sx={{
                    py: 1.5,
                    px: 5,
                    borderRadius: '8px',
                    textTransform: 'none',
                    fontWeight: 600,
                    fontSize: '1.1rem',
                    whiteSpace: 'nowrap',
                    '&:hover': {
